glsl3.vert:
precision highp float;
layout(std140) uniform CCGlobal {
  highp   vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_nativeSize;
  mediump vec4 cc_probeInfo;
  mediump vec4 cc_debug_view_mode;
};
layout(std140) uniform CCCamera {
  highp   mat4 cc_matView;
  highp   mat4 cc_matViewInv;
  highp   mat4 cc_matProj;
  highp   mat4 cc_matProjInv;
  highp   mat4 cc_matViewProj;
  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
#if USE_LOCAL
  layout(std140) uniform CCLocal {
    highp mat4 cc_matWorld;
    highp mat4 cc_matWorldIT;
    highp vec4 cc_lightingMapUVParam;
    highp vec4 cc_localShadowBias;
    highp vec4 cc_reflectionProbeData1;
    highp vec4 cc_reflectionProbeData2;
    highp vec4 cc_reflectionProbeBlendData1;
    highp vec4 cc_reflectionProbeBlendData2;
  };
#endif
in vec3 a_position;
in vec2 a_texCoord;
in vec4 a_color;
out vec4 color;
out vec2 uv0;
vec4 vert () {
  vec4 pos = vec4(a_position, 1);
  #if USE_LOCAL
    pos = cc_matWorld * pos;
  #endif
  pos = cc_matViewProj * pos;
  uv0 = a_texCoord;
  color = a_color;
  return pos;
}
void main() { gl_Position = vert(); }

glsl3.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture(tex, uv).rgb, texture(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture(tex, uv);
#endif
}
#if USE_ALPHA_TEST
  layout(std140) uniform ALPHA_TEST_DATA {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
    if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
    if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 color;
in vec2 uv0;
#if USE_TEXTURE
  uniform sampler2D cc_spriteTexture;
#endif
layout(std140) uniform Constants {
  float u_time;
  float u_intensity;
  float u_rimWidth;
  float u_sweepSpeed;
  float u_fireAmt;
  float u_shimmer;
  float u_prestige;
};
vec3 hue (float h) {
  return clamp(abs(fract(h + vec3(0.0, 0.6667, 0.3333)) * 6.0 - 3.0) - 1.0, 0.0, 1.0);
}
vec4 frag () {
  float a = 1.0;
  #if USE_TEXTURE
    a = CCSampleWithAlphaSeparated(cc_spriteTexture, uv0).a;
  #endif
  float phA = color.r * 6.2831;
  float phB = color.g;
  float pulse = 0.55 + 0.45 * sin(u_time * 5.0 + phA);
  vec2 g1 = uv0 - vec2(0.5 + 0.26 * sin(u_time * 0.7 + phA), 0.55 + 0.22 * cos(u_time * 0.9 + phA));
  float c1 = max(exp(-abs(g1.x) * 55.0), exp(-abs(g1.y) * 55.0)) * exp(-dot(g1, g1) * 22.0);
  vec2 g2 = uv0 - vec2(0.5 + 0.30 * cos(u_time * 0.5 + phA * 1.7), 0.5 + 0.28 * sin(u_time * 0.8 + phA * 1.3));
  float c2 = max(exp(-abs(g2.x) * 60.0), exp(-abs(g2.y) * 60.0)) * exp(-dot(g2, g2) * 26.0);
  float tw1 = 0.35 + 0.65 * pow(0.5 + 0.5 * sin(u_time * 9.0 + phA), 3.0);
  float tw2 = 0.30 + 0.70 * pow(0.5 + 0.5 * sin(u_time * 7.0 + phA + 2.1), 3.0);
  float glint = (c1 * tw1 + c2 * tw2) * a;
  float lo = 0.5 - u_rimWidth * 10.0;
  float rim = smoothstep(lo, 0.5, a) * (1.0 - smoothstep(0.5, 0.97, a));
  rim = pow(clamp(rim, 0.0, 1.0), 0.6) * (0.7 + 0.55 * pulse);
  vec3 rimCol = mix(vec3(1.0, 0.66, 0.34), vec3(1.0, 0.95, 0.82), 0.5 + 0.5 * sin(u_time * 3.0 + phA));
  float body = a * (0.16 + 0.13 * pulse);
  vec3 warm = vec3(1.0, 0.93, 0.76);
  vec3 rgb = warm * body
           + rimCol * rim * 0.95
           + vec3(1.0, 0.99, 0.95) * glint * 1.8;
  float outA = clamp(body + rim * 0.85 + glint * 1.5, 0.0, 1.0) * u_intensity * color.a;
  float diag = (uv0.x - uv0.y) * 0.70711;
  float ribT = fract(diag * 1.6 - u_time * 0.8);
  float ribbon = smoothstep(0.0, 0.06, ribT) * (1.0 - smoothstep(0.09, 0.26, ribT));
  vec3 iris = hue(diag * 0.85 + u_time * 0.12);
  float shine = ribbon * a * u_prestige;
  rgb += iris * shine * 1.15;
  outA = clamp(outA + shine * 0.8, 0.0, 1.0);
  vec4 col = vec4(rgb, outA);
  ALPHA_TEST(col);
  return col;
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

